import heapq

def match(orders):
    trades = []
    buy_heap = []  # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}  # id -> dict with side, price, qty, seq, active
    seq_counter = 0

    def add_to_book(oid, side, price, qty, seq):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def clean_buy_top():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            return (negprice, seq, oid)
        return None

    def clean_sell_top():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            return (price, seq, oid)
        return None

    def match_incoming(side, price, qty, is_market):
        # price is None if market order (no price limit)
        remaining = qty
        if side == 'buy':
            while remaining > 0:
                top = clean_sell_top()
                if top is None:
                    break
                sell_price, sell_seq, sell_id = top
                if not is_market and sell_price > price:
                    break
                info = book[sell_id]
                trade_qty = min(remaining, info['qty'])
                trades.append([None, sell_id, sell_price, trade_qty])  # placeholder for buy_id
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    info['active'] = False
                    heapq.heappop(sell_heap)
            return remaining
        else:
            while remaining > 0:
                top = clean_buy_top()
                if top is None:
                    break
                negprice, buy_seq, buy_id = top
                buy_price = -negprice
                if not is_market and buy_price < price:
                    break
                info = book[buy_id]
                trade_qty = min(remaining, info['qty'])
                trades.append([buy_id, None, buy_price, trade_qty])  # placeholder for sell_id
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    info['active'] = False
                    heapq.heappop(buy_heap)
            return remaining

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active']:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, is_market=False)
            # fill in incoming id in trades that were just added
            if side == 'buy':
                # fill buy_id for trades with None buy_id at end
                for t in trades:
                    if t[0] is None:
                        t[0] = oid
            else:
                for t in trades:
                    if t[1] is None:
                        t[1] = oid
            if remaining > 0:
                seq_counter += 1
                add_to_book(oid, side, price, remaining, seq_counter)

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, is_market=False)
            if side == 'buy':
                for t in trades:
                    if t[0] is None:
                        t[0] = oid
            else:
                for t in trades:
                    if t[1] is None:
                        t[1] = oid
            # discard remainder

        elif typ == 'market':
            _, oid, side, qty = order
            remaining = match_incoming(side, None, qty, is_market=True)
            if side == 'buy':
                for t in trades:
                    if t[0] is None:
                        t[0] = oid
            else:
                for t in trades:
                    if t[1] is None:
                        t[1] = oid
            # discard remainder

    return trades

